function mapSVG(){var pins=[["demand",150,34,"4 sky"],["growth",170,120,"3 growth"],["turgor",76,150,"2 turgor"],["anatomy",192,208,"1 section"],["embolism",66,262,"5 xylem"],["leaf",64,104,"6 leaf"],["field",44,398,"7 field"]];
  var s='<svg viewBox="0 0 260 440" role="img" aria-label="Course map: a plant drawn from root to leaf, with seven numbered stops pinned on it. 1 section at the stem, 2 microCT at the lower stem, 3 turgor and 4 growth at the leaves, 5 sky above the plant, 6 xylem in the stem, 7 leaf at the upper leaf, 8 field in the soil.">';
  s+='<rect x="0" y="0" width="260" height="90" fill="var(--sky)"/>';
  s+='<rect x="0" y="330" width="260" height="110" fill="var(--soil-3)"/><rect x="0" y="330" width="260" height="22" fill="var(--soil-4)"/>';
  s+='<path d="M130 330 L130 70" stroke="var(--ink)" stroke-width="5" fill="none"/>';
  [[130,110,-1],[130,160,1],[130,210,-1],[130,255,1]].forEach(function(l){var x=l[0],y=l[1],d=l[2];
    s+='<path d="M'+x+' '+y+' q '+(d*30)+' -26 '+(d*78)+' -16 q '+(d*-30)+' 22 '+(d*-78)+' 16z" fill="var(--psi-p-soft)" stroke="var(--psi-p)" stroke-width="1.5"/>'});
  s+='<path d="M130 330 q -20 40 -60 70 M130 330 q 10 50 40 90 M130 330 q 30 30 80 40 M130 330 q -40 20 -90 20" stroke="var(--ink)" stroke-width="1.5" fill="none"/>';
  s+='<path d="M130 440 L130 80" stroke="var(--psi-w)" stroke-width="2" stroke-dasharray="3 5"/>';
  pins.forEach(function(p){var wide=p[1]>130, hx=wide?p[1]-96:p[1]-10;
    s+='<a href="#/'+p[0]+'" aria-label="Go to stop '+p[3]+'">'+
      '<rect x="'+hx+'" y="'+(p[2]-13)+'" width="106" height="26" fill="transparent"/>'+
      '<circle cx="'+p[1]+'" cy="'+p[2]+'" r="6" fill="var(--surface)" stroke="var(--ink)" stroke-width="2"/>'+
      T(p[1]+(wide?-10:10),p[2]+4,p[3],{anchor:wide?"end":"start",fill:"var(--ink)",weight:600,size:13,halo:1})+'</a>'});
  return s+'</svg>'}

