function closeSheet(){if($("#sheet").hidden)return; $("#sheet").hidden=true; $("#scrim").hidden=true; $("#openSheet").focus()}
$("#openSheet").addEventListener("click",openSheet); $("#closeSheet").addEventListener("click",closeSheet); $("#scrim").addEventListener("click",closeSheet);
